command:
$ErrorActionPreference = "Stop"
Write-Host "===== BOOKMARK FOCUSED GUI RETEST ====="
git fetch origin main work/bookmarks-winui --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "git fetch failed" }
if ((git rev-parse origin/main).Trim() -ne "5228cbbfc24f56d61a84975545f1d8572e7deece") {
  throw "main moved after request snapshot"
}
$status = @(git status --short)
if ($status.Count -ne 0) {
  $status | ForEach-Object { Write-Host $_ }
  throw "persistent checkout has unexpected local changes"
}
if ((git branch --show-current) -ne "work/bookmarks-winui") {
  git checkout work/bookmarks-winui
  if ($LASTEXITCODE -ne 0) { throw "cannot checkout bookmark branch" }
}
git merge --ff-only origin/work/bookmarks-winui
if ($LASTEXITCODE -ne 0) { throw "cannot fast-forward bookmark branch" }
Write-Host "BOOKMARK_BRANCH_HEAD=$(git rev-parse HEAD)"

cmd /c test.bat source
if ($LASTEXITCODE -ne 0) { throw "source contracts failed" }

$env:FLY_MIGRATION_CONFIGURATION = "Release"
python -X utf8 tests\winui\test_bookmark_gui.py
if ($LASTEXITCODE -ne 0) { throw "bookmark GUI failed" }

if (-not (Test-Path "logs\capture-bookmark-visual.py")) {
  throw "capture helper missing"
}
$env:BOOKMARK_VISUAL_MODE = "after"
python -X utf8 logs\capture-bookmark-visual.py
if ($LASTEXITCODE -ne 0) { throw "after capture failed" }

python -X utf8 -c "from PIL import Image; from pathlib import Path; import hashlib; b=Path('logs/bookmark-visual-before.png'); a=Path('logs/bookmark-visual-after.png'); print('BEFORE_EXISTS',b.exists()); print('AFTER_EXISTS',a.exists()); print('BEFORE_SIZE',Image.open(b).size if b.exists() else None); print('AFTER_SIZE',Image.open(a).size if a.exists() else None); print('BEFORE_SHA256',hashlib.sha256(b.read_bytes()).hexdigest() if b.exists() else ''); print('AFTER_SHA256',hashlib.sha256(a.read_bytes()).hexdigest() if a.exists() else '')"
if ($LASTEXITCODE -ne 0) { throw "visual evidence metadata failed" }

git diff --check origin/main..HEAD
if ($LASTEXITCODE -ne 0) { throw "git diff --check failed" }
Write-Host "FINAL_STATUS"
git status --short
Write-Host "BOOKMARK_FOCUSED_RETEST_PASS"
